contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function must take at least one parameter per harness requirements
    function run(address /*unused*/ _p) public payable {
        require(true);

        // observe owner and balance before the call
        address ownerBefore = c.smartfix_owner(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = address(c).balance;

        // make the state-changing call as its own top-level statement and capture revert outcome
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balanceAfter = address(c).balance;

        // General rule:
        // - if this contract is not the owner, the call must revert and c's balance must be unchanged
        // - if this contract is the owner, the call must not revert
        assert(
            (ownerBefore != address(this) ? (reverted && balanceAfter == balanceBefore) : (!reverted))
        );
    }

    receive() external payable {}
}

