// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(address _p) internal {
        vm.assume(true);
        address ownerBefore;
        try c.smartfix_owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint256 balanceBefore = address(c).balance;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balanceAfter = address(c).balance;
        assertTrue((ownerBefore != address(this) ? (reverted && balanceAfter == balanceBefore) : (!reverted)));
    }

    function testFuzz_run(address _p) public {
        vm.assume(_p.code.length == 0 && uint160(_p) > 0xffff && _p != address(this) && _p != address(c) && _p != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _p != 0x000000000000000000636F6e736F6c652e6c6f67 && _p != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _p != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_p);
    }

    receive() external payable {}
}
